import { easeCubicInOut } from 'd3-ease';
import { interpolateNumber as interpolate } from 'd3-interpolate';

import {
  LineCanvasInstance,
  FnCanvasAccessor,
} from '../../types/canvas-shape.js';
import { areDatumsEqualBy } from '../datums.js';

/**
 * Check if current and prev line canvas are equal.
 * By comparing all incoming data and x/y accessors value.
 *
 * @param current - current bar canvas
 * @param prev - prev bar canvas
 * @returns boolean
 */
export function isLineCanvasEqual<Datum>(
  current: LineCanvasInstance<Datum>,
  prev: LineCanvasInstance<Datum>,
): boolean {
  if (!areDatumsEqualBy(current.data, prev.data, 'value')) {
    return false;
  }

  const isNotResizing =
    current.canvasWidth === prev.canvasWidth &&
    current.canvasHeight === prev.canvasHeight;

  if (isNotResizing) {
    return (
      prev.y(prev.data[0]) === current.y(current.data[0]) &&
      current.x(current.data[0]) === prev.x(prev.data[0])
    );
  }

  return true;
}

interface AnimationPoints<Datum> {
  start?: Datum;
  end: Datum;
}

/**
 * Get start and end points to be animated.
 *
 * @param canvas - current canvas, end
 * @param prevCanvas - previous canvas, start
 * @returns - array of start and end points store by current canvas (End) position
 */
function getAnimationPoints<Datum>(
  canvas: LineCanvasInstance<Datum>,
  prevCanvas?: LineCanvasInstance<Datum>,
) {
  const startEndPoints: AnimationPoints<Datum>[] = [];
  const dataLength = canvas.data.length;

  for (let i = 0; i < dataLength; i++) {
    const end = canvas.data[i];

    if (!prevCanvas) {
      startEndPoints.push({ start: undefined, end });

      continue;
    }

    const prevPoint = prevCanvas.data[i];

    startEndPoints.push({ start: prevPoint, end });
  }

  return startEndPoints;
}

/**
 * LineCanvas animation.
 * An interpolation between start and end canvas (prev and current).
 * This method will return the modified X/Y accessors based on progress
 *
 * @param canvas - current canvas, where the animation ends
 * @param progress - the amount of animation progress. calc of: (currentTime - startTimestamp) / animationDuration
 * @param printLine - print bar call back
 * @param prevCanvas - previous canvas, the animation starts
 * @returns - printLine call back with modified X/Y accessors
 */
export function lineAnimation<Datum>(
  canvas: LineCanvasInstance<Datum>,
  progress: number,
  printLine: (x: FnCanvasAccessor<Datum>, y: FnCanvasAccessor<Datum>) => void,
  prevCanvas?: LineCanvasInstance<Datum>,
) {
  const animationPoints = getAnimationPoints<Datum>(canvas, prevCanvas);
  const interpolation = (start: number, end: number) =>
    interpolate(start, end)(easeCubicInOut(progress));

  const x = (point: Datum, index: number) => {
    const { start, end } = animationPoints[index];

    if (start && prevCanvas) {
      return interpolation(prevCanvas.x(start), canvas.x(end));
    }

    return canvas.x(end);
  };

  const y = (point: Datum, index: number) => {
    const { start, end } = animationPoints[index];

    if (start && prevCanvas) {
      return interpolation(prevCanvas.y(start), canvas.y(end));
    }

    return interpolation(canvas.zeroAxis(point), canvas.y(end));
  };

  return printLine(x, y);
}
